"""Pydantic models for the agent-build-plan lifecycle (Copilot v2 slice 1)."""

from __future__ import annotations

from datetime import datetime
from enum import Enum

from pydantic import BaseModel, field_validator, model_validator

MAX_OPEN_QUESTIONS = 5


class PlannedSkill(BaseModel):
    """A single Mantle skill proposed by the plan.

    Maps directly onto ``skills/<id>/skill.md``: ``id`` is the skill's folder
    name, ``description`` is the routing description an orchestrator matches
    against, and ``outline`` is the step-by-step body in plain language.

    Whitespace is stripped and blank list entries are dropped on construction;
    a blank ``id`` or ``description`` is rejected.
    """

    id: str
    description: str
    outline: list[str]
    memory: list[str] = []
    responses: list[str] = []

    @field_validator("id", "description")
    @classmethod
    def _strip(cls, value: str) -> str:
        return value.strip()

    @field_validator("outline", "memory", "responses")
    @classmethod
    def _strip_entries(cls, value: list[str]) -> list[str]:
        return [entry.strip() for entry in value if entry.strip()]

    @model_validator(mode="after")
    def _reject_blank_fields(self) -> PlannedSkill:
        if not self.id:
            raise ValueError("Every skill needs a non-blank name.")
        if not self.description:
            raise ValueError(f"Skill '{self.id}' needs a non-blank description.")
        return self


class AgentBuildPlan(BaseModel):
    """The structured build plan produced (or edited) for one Mantle agent.

    The invariants below live on the model rather than on the planner agent so
    they hold for every plan that enters the system, whether the planner
    produced it or a client sent it to the direct-edit endpoint. A planner run
    that violates one fails output validation, which pydantic-ai turns into a
    model retry.
    """

    name: str
    persona_summary: str
    skills: list[PlannedSkill]
    assumptions: list[str]
    open_questions: list[str]

    @field_validator("name", "persona_summary")
    @classmethod
    def _strip(cls, value: str) -> str:
        return value.strip()

    @field_validator("assumptions", "open_questions")
    @classmethod
    def _strip_entries(cls, value: list[str]) -> list[str]:
        return [entry.strip() for entry in value if entry.strip()]

    @model_validator(mode="after")
    def _check_plan_invariants(self) -> AgentBuildPlan:
        if not self.name:
            raise ValueError("The plan needs a non-blank agent name.")
        if not self.persona_summary:
            raise ValueError("The plan needs a non-blank persona_summary.")
        if not self.skills:
            raise ValueError("The plan must include at least one skill.")
        if len(self.open_questions) > MAX_OPEN_QUESTIONS:
            raise ValueError(
                f"Too many open_questions ({len(self.open_questions)}); keep only "
                f"the most important {MAX_OPEN_QUESTIONS}."
            )

        seen_names: set[str] = set()
        for skill in self.skills:
            normalized_name = skill.id.lower()
            if normalized_name in seen_names:
                raise ValueError(
                    f"Duplicate skill name '{skill.id}'; give every skill a "
                    f"unique name."
                )
            seen_names.add(normalized_name)
        return self


class PlanStatus(str, Enum):
    """Lifecycle status of an agent build plan."""

    DRAFT = "draft"
    APPROVED = "approved"
    BUILDING = "building"
    BUILT = "built"
    FAILED = "failed"
    DISCARDED = "discarded"


class PlanRevision(BaseModel):
    """One immutable, versioned snapshot of a plan."""

    revision: int
    source: str
    plan: AgentBuildPlan
    created_at: datetime


class AgentPlanRecord(BaseModel):
    """A plan and its latest revision, as persisted in the store."""

    plan_id: str
    agent_id: str
    status: PlanStatus
    prompt: str
    latest_revision: PlanRevision
    job_id: str | None = None
    created_at: datetime
    updated_at: datetime
